<script setup lang="ts">import {ref} from 'vue';import TimelineSteps from '../common/TimelineSteps.vue';import EntityTabs from '../common/EntityTabs.vue';defineProps<{status?:string}>();const steps=['项目立项','需求调研','系统开发','UAT验收','割接上线','终验维保'];const activeTab=ref('overview');</script>
